const base = { canal: 'whatsapp', destinatario: 'sessao-simulada', remetente: '10000000000@c.us', mensagem: 'Olá, gostaria de conhecer os serviços.', metadados: { canal_id: '11111111-1111-4111-8111-111111111111', agente_id: '22222222-2222-4222-8222-222222222222' } };
return [
  { json: { cenario: 'válido', ...base, id_externo: 'sim-001' } },
  { json: { cenario: 'duplicado', ...base, id_externo: 'sim-001' } },
  { json: { cenario: 'inválido', canal: 'whatsapp', id_externo: 'sim-002' } }
];

const seen = new Set();
const required = ['canal', 'destinatario', 'remetente', 'id_externo', 'mensagem'];
return $input.all().map(({ json: event }) => {
  const invalid = required.find((field) => typeof event[field] !== 'string' || !event[field].trim());
  if (invalid) return { json: { cenario: event.cenario, aceito: false, motivo: `${invalid} é obrigatório`, entrega_externa: false } };
  if (seen.has(event.id_externo)) return { json: { cenario: event.cenario, aceito: false, duplicado: true, motivo: 'Evento duplicado no lote', entrega_externa: false } };
  seen.add(event.id_externo);
  return { json: { cenario: event.cenario, aceito: true, duplicado: false, rag: 'cache ausente; contexto simulado', acao: 'responder', resposta_simulada: 'Olá! Posso ajudar com informações sobre nossos serviços.', entrega_externa: false } };
});
